param(
  [switch]$SkipBuild
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Root = (Get-Location).Path
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$Backup = Join-Path $Root ".orcaly-backups\isolar-pagamentos-$Stamp"
$Utf8 = New-Object System.Text.UTF8Encoding($false)

function Full([string]$Path) {
  Join-Path $Root ($Path -replace "/", "\")
}

function Backup-File([string]$Path) {
  $Source = Full $Path
  if (-not (Test-Path -LiteralPath $Source)) { return }
  $Destination = Join-Path $Backup ($Path -replace "/", "\")
  New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
  Copy-Item -LiteralPath $Source -Destination $Destination -Force
}

function Write-Base64File([string]$Path, [string]$Encoded) {
  $Destination = Full $Path
  New-Item -ItemType Directory -Force -Path (Split-Path $Destination -Parent) | Out-Null
  $Text = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Encoded))
  [IO.File]::WriteAllText($Destination, $Text.TrimEnd() + "`n", $Utf8)
  Write-Host "[OK] $Path" -ForegroundColor Green
}

if (-not (Test-Path -LiteralPath (Join-Path $Root "package.json"))) {
  throw "Execute este script na raiz do projeto Orcaly."
}

$Branch = (& git branch --show-current 2>$null | Out-String).Trim()
if ($Branch -ne "feature/asaas-sandbox") {
  throw "Branch atual: $Branch. Execute na branch feature/asaas-sandbox."
}

$Targets = @(
  "lib/signup-checkout.ts",
  "lib/subscription-service.ts",
  "lib/mercado-pago.ts",
  "components/checkout/SignupCheckout.tsx",
  "components/subscription/MercadoPagoSubscriptionCheckout.tsx",
  "components/checkout/CheckoutClient.tsx",
  "lib/payments/checkout-service.ts",
  "app/api/mercado-pago/webhook-leads/route.ts",
  "app/api/assinatura/checkout/webhook/route.ts",
  "app/api/marketplace/payments/webhook/mercado-pago/route.ts",
  ".env.example"
)

foreach ($Target in $Targets) {
  if (-not (Test-Path -LiteralPath (Full $Target))) {
    throw "Arquivo necessario nao encontrado: $Target"
  }
}

New-Item -ItemType Directory -Force -Path $Backup | Out-Null
foreach ($Target in $Targets) { Backup-File $Target }

Write-Host ""
Write-Host "==================================================" -ForegroundColor Cyan
Write-Host "ORCALY - TRES FLUXOS DE PAGAMENTO ISOLADOS" -ForegroundColor Cyan
Write-Host "Cadastro + assinatura + marketplace" -ForegroundColor Cyan
Write-Host "==================================================" -ForegroundColor Cyan

Write-Base64File "lib/payments/signup/mercado-pago.ts" ""

Write-Base64File "lib/payments/subscription/mercado-pago.ts" ""

Write-Base64File "lib/payments/marketplace/config.ts" ""

Write-Base64File "docs/pagamentos-isolados.md" ""

Write-Base64File "scripts/auditar-isolamento-pagamentos.cjs" ""

$PatcherPath = Join-Path $Root ".orcaly-isolar-pagamentos-$Stamp.cjs"
$PatcherCode = [Text.Encoding]::UTF8.GetString(
  [Convert]::FromBase64String("")
)
[IO.File]::WriteAllText($PatcherPath, $PatcherCode, $Utf8)

try {
  Write-Host ""
  Write-Host "==> Separando os tres dominios" -ForegroundColor Cyan
  & node $PatcherPath
  if ($LASTEXITCODE -ne 0) {
    throw "O patch de isolamento nao foi concluido."
  }
} finally {
  Remove-Item -LiteralPath $PatcherPath -Force -ErrorAction SilentlyContinue
}

Write-Host ""
Write-Host "==> Migrando variaveis locais sem mostrar segredos" -ForegroundColor Cyan

$EnvPath = Join-Path $Root ".orcaly-migrar-env-$Stamp.cjs"
$EnvCode = [Text.Encoding]::UTF8.GetString(
  [Convert]::FromBase64String("")
)
[IO.File]::WriteAllText($EnvPath, $EnvCode, $Utf8)

try {
  & node $EnvPath
  if ($LASTEXITCODE -ne 0) {
    throw "A migracao das variaveis locais falhou."
  }
} finally {
  Remove-Item -LiteralPath $EnvPath -Force -ErrorAction SilentlyContinue
}

Write-Host ""
Write-Host "==> Auditando configuracao local" -ForegroundColor Cyan
& node (Full "scripts/auditar-isolamento-pagamentos.cjs")
$AuditCode = $LASTEXITCODE

if ($AuditCode -ne 0) {
  Write-Host ""
  Write-Host "O codigo foi isolado, mas faltam variaveis locais obrigatorias." -ForegroundColor Yellow
  Write-Host "Nenhum commit foi criado." -ForegroundColor Yellow
  Write-Host "Backup: $Backup" -ForegroundColor Yellow
  exit $AuditCode
}

if (-not $SkipBuild) {
  Write-Host ""
  Write-Host "==> Limpando cache do Next" -ForegroundColor Cyan
  Remove-Item -Recurse -Force (Join-Path $Root ".next") -ErrorAction SilentlyContinue

  Write-Host ""
  Write-Host "==> Executando build" -ForegroundColor Cyan
  & npm.cmd run build
  $BuildCode = $LASTEXITCODE
  Write-Host "BUILD_EXIT_CODE=$BuildCode"

  if ($BuildCode -ne 0) {
    Write-Host ""
    Write-Host "O build falhou. Nenhum commit foi criado." -ForegroundColor Red
    Write-Host "Backup: $Backup" -ForegroundColor Yellow
    exit $BuildCode
  }
}

Write-Host ""
Write-Host "==================================================" -ForegroundColor Magenta
Write-Host "TRES FLUXOS ISOLADOS NO CODIGO" -ForegroundColor Magenta
Write-Host "==================================================" -ForegroundColor Magenta
Write-Host "Cadastro usa somente MP_SIGNUP_*"
Write-Host "Assinatura usa somente MP_SUBSCRIPTION_*"
Write-Host "Marketplace usa MP_MARKETPLACE_* e tokens OAuth por empresa"
Write-Host "Variaveis antigas foram mantidas somente para rollback."
Write-Host "Nenhum commit ou deploy foi criado."
Write-Host "Backup: $Backup"
